SELECT r."build_manifest_json", r."diagnostics_json", r."generation_no", r."source_revision", r."status", r."requested_by", r."requested_at", r."report_count", r."activated_at", r."retired_at" FROM (SELECT generation."generation_no", generation."source_revision", generation."status", generation."report_count", generation."build_manifest_json", generation."diagnostics_json", generation."requested_by", generation."requested_at", generation."activated_at", generation."retired_at" FROM  (SELECT g.* FROM runtime_generations g
)  generation WHERE 1 = 1) r WHERE $criteria.CompositeIn("r", $GenerationKeys)